tool_input.content:
export const ACCOUNT_STATE_NORMAL = '0'
export const ACCOUNT_STATE_FROZEN = '1'

export const AUTO_FREEZE_REASON = '多次输入错误密码'

export const FREEZE_REASON_OPTIONS = [
  { dictLabel: AUTO_FREEZE_REASON, dictValue: AUTO_FREEZE_REASON },
  { dictLabel: '管理员手动冻结', dictValue: '管理员手动冻结' },
  { dictLabel: '其他', dictValue: '其他' }
]

export const ACCOUNT_STATE_OPTIONS = [
  { dictLabel: '解冻', dictValue: ACCOUNT_STATE_NORMAL },
  { dictLabel: '冻结', dictValue: ACCOUNT_STATE_FROZEN }
]

function normalizeState(state) {
  if (state === null || state === undefined || state === '') {
    return ACCOUNT_STATE_NORMAL
  }
  return String(state).trim()
}

export function isAccountFrozen(userAccountState) {
  return normalizeState(userAccountState) === ACCOUNT_STATE_FROZEN
}

/**
 * 归一化接口返回的冻结字段
 */
export function normalizeFreezeFields(data = {}) {
  return {
    userAccountState: normalizeState(data.userAccountState),
    freezeTime: data.freezeTime,
    freezeReason: data.freezeReason
  }
}

/**
 * 格式化为 YYYY年M月D日
 */
export function formatFreezeTime(dateStr) {
  if (!dateStr) return ''
  const d = new Date(dateStr)
  if (Number.isNaN(d.getTime())) return dateStr
  return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`
}

/**
 * 冻结原因是否不可编辑（系统自动冻结）
 */
export function isFreezeReasonDisabled(userAccountState, freezeReason, originUserAccountState) {
  if (!isAccountFrozen(userAccountState)) return true
  return normalizeState(originUserAccountState) === ACCOUNT_STATE_FROZEN && freezeReason === AUTO_FREEZE_REASON
}

/**
 * 构建保存时的冻结相关字段，并清理不应提交的字段
 */
export function applyFreezeSavePayload(formData) {
  const result = { ...formData }
  result.userAccountState = formData.userAccountState || ACCOUNT_STATE_NORMAL
  if (result.userAccountState === ACCOUNT_STATE_FROZEN) {
    result.freezeReason = formData.freezeReason
  } else {
    delete result.freezeReason
  }
  delete result.freezeTime
  return result
}

/**
 * 冻结原因校验（冻结且非系统自动原因时必填）
 */
export function validateFreezeReason(userAccountState, freezeReason) {
  if (!isAccountFrozen(userAccountState)) return true
  if (freezeReason === AUTO_FREEZE_REASON) return true
  return freezeReason && String(freezeReason).trim() !== ''
}

/**
 * 构建查看模式 contentInfo 项
 */
export function buildFreezeContentInfo(form, options = {}) {
  const { layout, accountStateOptions = ACCOUNT_STATE_OPTIONS } = options
  const items = [{
    label: '账号冻结状态',
    value: form.userAccountState || ACCOUNT_STATE_NORMAL,
    layout,
    type: 'tag',
    options: accountStateOptions
  }]
  const frozen = isAccountFrozen(form.userAccountState)
  const hasFreezeHistory = Boolean(form.freezeTime || form.freezeReason)
  if (!frozen && !hasFreezeHistory) return items

  items.push({
    label: frozen ? '冻结时间' : '上次冻结时间',
    value: formatFreezeTime(form.freezeTime) || '-',
    layout,
    type: 'text'
  })
  items.push({
    label: frozen ? '冻结原因' : '上次冻结原因',
    value: form.freezeReason || '-',
    layout,
    type: 'text'
  })
  return items
}

